lib.map((c, i) => {
      const showName = c.name && c.name.trim();
      const title = (showName ? `【${esc(c.name)}】\n` : '') + esc(c.cmd);
      // 名称/命令都可点击编辑（弹出模态框）；命令内容只读展示
      return `<div class="cmd-item" title="${title}">
        <span class="text cmd-edit-trigger" data-i="${i}" title="点击编辑" style="display:flex;flex-direction:column;line-height:1.3;min-width:0;flex:1;cursor:pointer">
          ${showName ? `<span class="name">${esc(c.name)}</span><span class="cmd-sub">${esc(c.cmd)}</span>` : `<span class="cmd-no-name">＋ 备注</span><span class="cmd-sub">${esc(c.cmd)}</span>`}
        </span>
        <button class="run" data-i="${i}">发送</button>
        <button class="edit" data-i="${i}" title="编辑">✎</button>
        <button class="del" data-i="${i}" title="删除">✕</button>
      </div>`;
    }).join

fetch('/api/history?port_id=' + encodeURIComponent(activePortId))
      .then(r => r.json()).then(j => {
        const hist = j.history || [];
        const rec = $('cmdRecent');
        if (!hist.length) { rec.innerHTML = '<div class="cmd-empty">暂无历史</div>'; return; }
        rec.innerHTML = hist.slice(-15).reverse().map(c =>
          `<div class="cmd-item"><span class="text" title="${esc(c)}">${esc(c)}</span><button class="run" data-cmd="${esc(c)}">重发</button></div>`
        ).join('');
        rec.querySelectorAll('.run').forEach(b => b.onclick = () => sendCmd(b.dataset.cmd));
      }).catch

hist.slice(-15).reverse().map(c =>
          `<div class="cmd-item"><span class="text" title="${esc(c)}">${esc(c)}</span><button class="run" data-cmd="${esc(c)}">重发</button></div>`
        ).join

entries.map((e, i) => {
        const arrow = foldable && e.kids
          ? `<span class="ed-outline-fold" data-i="${i}">${e._folded ? '▸' : '▾'}</span>` : (foldable ? '<span class="ed-outline-fold" style="visibility:hidden">▾</span>' : '');
        return `<div class="ed-outline-item${foldable ? ' ed-outline-foldable' : ''}" data-i="${i}" style="padding-left:${(e.level-1)*12+8}px">${arrow}${esc(foldable ? (e.text || '') : (e.kind ? e.kind + ' ' : '') + e.text)}</div>`;
      }).join

tsOutline(src, ext).then(entries => {
        if (entries && entries.err) {
          // 语法树失败：面板显示原因（不再无声回落——上次 Language 导出写错就无声了）
          conn.outlineList.innerHTML = `<div class="ed-outline-empty">语法树解析失败<br>${esc(entries.err)}</div>`;
          conn.outlineStats.innerHTML = '';
          return;
        }
        if (entries && entries.length) renderEntries(entries);
        else finishCode();
      }).catch

fetch('/api/ed/default_name?ext=' + encodeURIComponent(curExt)).then(r => r.json()).then(j => {
      if (j.ok && conn._renaming && !inp._userEdited && document.activeElement === inp) {
        inp.value = _edBaseName(j.name); fit();
      }
    }).catch

hits.map((l, i) =>
    `<div class="hline" data-i="${i}" title="${esc(l.text)}"><span class="hrow">${l.line}</span> ${esc(l.text.length > 200 ? l.text.slice(0,200)+'…' : l.text)}</div>`
  ).join

fetch('/api/log_page?name=' + encodeURIComponent(ls.name) + '&offset=' + off + '&limit=' + lim)
          .then(r => r.json()).then(j => {
            if (j.ok) (j.lines || []).forEach((l, idx) => ls.rows.set(off + idx, l));
          }).catch

hits.map((l, idx) => {
    const text = esc((l.text || '').replace(/\r/g, ''));
    return `<div class="hline" data-idx="${idx}" title="${text}"><span class="hrow">${l.row}</span> ${text}</div>`;
  }).join

calls.slice(-20).reverse().map(c => {
      const d = new Date(c.ts * 1000);
      const ts = d.toTimeString().slice(0, 8);
      return `<div class="mcp-call ${c.ok ? 'ok' : 'fail'}"><span class="ctime">${ts}</span><span class="ctool">${esc(c.tool)}</span> <span class="cargs">${esc(c.args || '')}</span></div>`;
    }).join

ports.map(p =>
    `<span class="chip ${p === filter ? 'active' : ''}" data-port="${esc(p)}">${esc(p === 'ALL' ? '全部' : p)}</span>`
  ).join

recent.map(it => {
    const kc = kwClassOf(it.text || '');
    return `<div class="sense-line ${kc}" data-port="${esc(it.port)}"><span class="port-tag">[${esc(it.port)}]</span>${esc((it.text || '').slice(0, 200))}</div>`;
  }).join

transfers.map(t => {
            const active = t.status !== 'done' && t.status !== 'error';
            // get=设备下载(RRQ,有total)，put=设备上传(WRQ,total可能null)
            const icon = t.status === 'done' ? '✓' : t.status === 'error' ? '✗' : (t.kind === 'get' ? '⬆' : '⬇');
            const hasTotal = active && t.total;
            const pct = hasTotal ? Math.min(100, Math.round(t.bytes / t.total * 100)) : 0;
            const size = t.status === 'done'
              ? _fmtSize(t.bytes)
              : (hasTotal ? `${_fmtSize(t.bytes)}/${_fmtSize(t.total)} · ${pct}%` : _fmtSize(t.bytes));
            const tip = (t.kind === 'get' ? '设备下载' : '设备上传') + (t.via === 'hfs' ? ' · HFS' : ' · TFTP');
            // 来源标签：区分 TFTP/HFS 传输
            const viaTag = `<span class="tftp-via ${t.via === 'hfs' ? 'via-hfs' : 'via-tftp'}">${t.via === 'hfs' ? 'HFS' : 'TFTP'}</span>`;
            // 无 total（WRQ 未协商 tsize）时进度条用不确定条纹动画，至少表明在传输
            const barStyle = hasTotal ? `width:${pct}%` : '';
            const barClass = hasTotal ? '' : 'indeterminate';
            return `<div class="tftp-item ${active ? 'active' : t.status}" title="${tip} · ${t.peer}${t.err ? ' · ' + esc(t.err) : ''}">
              <span class="icon">${icon}</span>
              ${viaTag}
              <span class="name">${esc(t.filename)}</span>
              <span class="size">${size}</span>
              <div class="bar ${barClass}"><i style="${barStyle}"></i></div>
            </div>`;
          }).join
